/** The demo copy for the active interface language, falling back to English then Spanish. */
export function studyDemoText(source: string): string {
  const entry = STUDY_DEMO_TEXT[source];
  if (!entry) return source;
  return entry[normalizeUiLanguage(getSettings().uiLanguage)] ?? entry.en ?? entry.es;
}
